WITH feature_rows AS (SELECT b.mktcode,b.tgtcode,b.bizdate,ABS(b.lastPx / 10000.0-t.ma5)/NULLIF(GREATEST(ABS(b.lastPx / 10000.0),ABS(t.ma5)),0)<=0.03 AS matched FROM `newzl`.`hsj_stock_hq_basic` b LEFT JOIN `newzl`.`hsj_stock_hq_basic_technical` t ON t.mktcode=b.mktcode AND t.tgtcode=b.tgtcode AND t.bizdate=b.bizdate), ranked_rows AS (SELECT mktcode,tgtcode,bizdate,matched,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate DESC) AS lookback_row FROM feature_rows), selected_rows AS (SELECT mktcode,tgtcode,bizdate,matched FROM ranked_rows WHERE lookback_row<=20), sequenced AS (SELECT mktcode,tgtcode,bizdate,matched,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS all_seq FROM selected_rows), matched_rows AS (SELECT mktcode,tgtcode,bizdate,all_seq,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS matched_seq FROM sequenced WHERE matched=TRUE), runs AS (SELECT mktcode,tgtcode,all_seq-matched_seq AS run_id,COUNT(*) AS run_length FROM matched_rows GROUP BY mktcode,tgtcode,all_seq-matched_seq), qualified AS (SELECT mktcode,tgtcode FROM runs GROUP BY mktcode,tgtcode HAVING MAX(run_length)>=3) SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN qualified q ON q.mktcode=b.mktcode AND q.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14';
